Upon new zone insert, we need to run an queueable job, code snippet to run the job:-

{noformat}Set<Id> accids = new Set<Id>();
List<CaseTriggerHandler.QueueableWrapper> lstQueueWrap = new List<CaseTriggerHandler.QueueableWrapper>();
List<String> slt = new List<String>();
Set<Id> seeeey = new Set<Id>();
for(City_Zone__c cz : [select id,City__c from city_zone__c where createddate = today]) {
	seeeey.add(cz.City__c);
}
for(Account acc : [SELECT id FROM Account where Zone__c = null AND Location__Latitude__s != null AND City__c IN:seeeey]) {
    slt.add(acc.id);
}
for(String accId : slt) {
    accids.add(accId);
    if(accids.size() == 40) {
        CaseTriggerHandler.QueueableWrapper q1 = new CaseTriggerHandler.QueueableWrapper();
        q1.actionType = 'updateAccountZone';
        q1.mapOfData = new Map<String,Object>();
        q1.mapOfData.put('accIds',accids);
        lstQueueWrap.add(q1);
        accids = new Set<Id>();
    }
}
if(accids.size() > 0) {
    CaseTriggerHandler.QueueableWrapper q1 = new CaseTriggerHandler.QueueableWrapper();
    q1.actionType = 'updateAccountZone';
    q1.mapOfData = new Map<String,Object>();
    q1.mapOfData.put('accIds',accids);
    lstQueueWrap.add(q1);
    accids = new Set<Id>();
}
System.enqueueJob(new Queueable_Generic(lstQueueWrap));{noformat}

